import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

NCOLS = 15

def norm_key(x):
    if isinstance(x, str):
        s = x.strip()
        if s == "":
            return None
        try:
            return int(s)
        except ValueError:
            try:
                return float(s)
            except ValueError:
                return s
    if isinstance(x, float) and x.is_integer():
        return int(x)
    return x

def clean(x):
    if isinstance(x, str):
        s = x.strip()
        return s if s != "" else None
    return x

def find_sheet(names, target):
    for n in names:
        if n.strip() == target:
            return n
    for n in names:
        if target.lower() in n.lower():
            return n
    raise KeyError(target)

main_name = find_sheet(vals.sheetnames, "Main unique ID")
get_name = find_sheet(vals.sheetnames, "Result what i am getting")

main_ws = vals[main_name]
get_ws = vals[get_name]

header = [clean(get_ws.cell(row=1, column=c).value) for c in range(1, NCOLS + 1)]

existing = {}
for r in range(2, get_ws.max_row + 1):
    uid = norm_key(get_ws.cell(row=r, column=1).value)
    if uid is None:
        continue
    row_vals = [clean(get_ws.cell(row=r, column=c).value) for c in range(1, NCOLS + 1)]
    existing[uid] = row_vals

main_ids = []
for r in range(2, main_ws.max_row + 1):
    uid = norm_key(main_ws.cell(row=r, column=1).value)
    if uid is None:
        continue
    main_ids.append(uid)

if "MyResult" in wb.sheetnames:
    ws = wb["MyResult"]
else:
    ws = wb.create_sheet("MyResult")

# Clear the graded answer region first.
for r in range(1, 21):
    for c in range(1, NCOLS + 1):
        ws.cell(row=r, column=c, value=None)

for c, v in enumerate(header, start=1):
    ws.cell(row=1, column=c, value=v)

for i, uid in enumerate(main_ids, start=2):
    row_vals = existing.get(uid)
    if row_vals is None:
        row_vals = [uid] + [None] * (NCOLS - 1)
    else:
        row_vals = list(row_vals)
        row_vals[0] = uid
        row_vals = (row_vals + [None] * NCOLS)[:NCOLS]

    for c, v in enumerate(row_vals, start=1):
        ws.cell(row=i, column=c, value=clean(v))

wb.save(OUT)

print("main_ids:", len(main_ids))
print("existing_rows:", len(existing))
print("first_rows:", [ws.cell(row=r, column=1).value for r in range(2, 7)])
